WORKER="import importlib.util, json, sys, time, traceback\nfrom pathlib import Path\nfrom fractions import Fraction\nsys.dont_write_bytecode = True\nimport hashlib, copy\nPRIMITIVES = ('floor_checked', 'ceil_checked', 'times', 'over', 'enclose', 'plus', 'opposite', 'intersect', 'product')\n\ndef fresh_counts():\n    result = {k: 0 for k in ('floor', 'ceiling', 'multiply', 'divide', 'convert', 'plus', 'negate', 'clip', 'products', 'zero_operand_multiplications')}\n    result['sign_cases'] = [0] * 9\n    return result\n\ndef identity_for(index, output):\n    fixed = (Path('scripts/four-rational-kernels/step-417') / ('n-' + str(index))).resolve()\n    return (index, str(fixed), str(Path(output).resolve()), 'fixed_replay_422_' + str(index), hashlib.sha256((fixed / 'replay.py').read_bytes()).hexdigest())\n\ndef check_identity(identity, fixed, output, module, original_module):\n    assert isinstance(identity, tuple) and len(identity) == 5\n    assert type(identity[0]) is int and identity[0] in (3, 4, 5, 6)\n    assert all((type(x) is str for x in identity[1:]))\n    assert str(fixed.resolve()) == identity[1] and str(output.resolve()) == identity[2]\n    assert fixed.name == output.name == 'n-' + str(identity[0])\n    assert module is original_module and module.__name__ == identity[3]\n    assert Path(module.__file__).resolve() == fixed / 'replay.py'\n    assert hashlib.sha256((fixed / 'replay.py').read_bytes()).hexdigest() == identity[4]\n    assert module.SCALE == 2 ** 256\n\ndef check_captures(module, wrappers, originals, signed, grid):\n    assert len(wrappers) == 9 and len({id(f) for f in wrappers}) == 9\n    old_names = ('old_floor', 'old_ceil', 'old_times', 'old_over', 'old_enc', 'old_plus', 'old_neg', 'old_clip', 'old_product')\n    evidence = []\n    for name, fn, old_name, old in zip(PRIMITIVES, wrappers, old_names, originals, strict=True):\n        assert getattr(module, name) is fn and fn is not old\n        closure = dict(zip(fn.__code__.co_freevars, (cell.cell_contents for cell in fn.__closure__), strict=True))\n        assert closure[old_name] is old and closure['signed'] is signed\n        if 'D' in closure:\n            assert closure['D'] == grid\n        if 'replay' in closure:\n            assert closure['replay'] is module\n        evidence.append({'primitive': name, 'closure_names': sorted(closure), 'original_captured': True, 'counter_captured': True})\n    return evidence\nIDENTITY = identity_for(int(sys.argv[1]), sys.argv[2])\nOLD = Path(IDENTITY[1])\nOUT = Path(IDENTITY[2])\nSTART = float(sys.argv[3])\nsentinel = -422\nstate = {'n': IDENTITY[0], 'stage': 'setup', 'panels': 0}\n\ndef read(name):\n    return json.loads((OLD / name).read_text())\n\ndef save(name, obj):\n    (OUT / name).write_text(json.dumps(obj, sort_keys=True, separators=(',', ':')) + '\\n')\n\ndef progress(stage, panels):\n    state.update(stage=stage, panels=panels)\n    assert time.monotonic() - START < 174\n    save('working.json', {**state, 'elapsed_seconds': time.monotonic() - START})\ntry:\n    spec = importlib.util.spec_from_file_location(IDENTITY[3], OLD / 'replay.py')\n    replay = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(replay)\n    D = replay.SCALE\n    assert D == 2 ** 256\n    signed = {k: 0 for k in ('floor', 'ceiling', 'multiply', 'divide', 'convert', 'plus', 'negate', 'clip', 'products', 'zero_operand_multiplications')}\n    signed['sign_cases'] = [0] * 9\n    original_module = replay\n    before_identity = IDENTITY\n    before_paths = (OLD, OUT)\n    original_primitives = tuple((getattr(replay, k) for k in PRIMITIVES))\n    check_identity(IDENTITY, OLD, OUT, replay, original_module)\n    installer_namespace = {}\n    exec(compile((OUT.parent / 'installer.py').read_text(), 'installer-422', 'exec'), installer_namespace)\n    wrappers = installer_namespace['install'](replay, D, signed, save)\n    assert IDENTITY == before_identity and (OLD, OUT) == before_paths and (sentinel == -422)\n    check_identity(IDENTITY, OLD, OUT, replay, original_module)\n    captures = check_captures(replay, wrappers, original_primitives, signed, D)\n    assert signed == fresh_counts() and replay.LEDGER == {}\n    save('identity-before-replay.json', {'identity': IDENTITY, 'captures': captures, 'sentinel': sentinel})\n    parameter = read('parameter.json')\n    assert parameter == json.loads(Path('scripts/first-rational-kernel/step-404/parameter.json').read_text())\n    assert parameter['midpoint'] == [73775804382331484748893662180180200545104154546089041648426948815067512948607, 2 ** 257]\n    final = read('kernel.json')\n    progress('replay', 0)\n    with (OLD / 'panels.jsonl').open() as handle:\n        report = replay.run(parameter, (json.loads(line) for line in handle), final, progress)\n    report = copy.deepcopy(report)\n    save('returned-report.json', report)\n    signed = copy.deepcopy(signed)\n    counts = copy.deepcopy(replay.LEDGER)\n    save('returned-ledger-and-signed.json', {'counts': counts, 'signed': signed})\n    assert IDENTITY == before_identity and (OLD, OUT) == before_paths and (sentinel == -422)\n    check_identity(IDENTITY, OLD, OUT, replay, original_module)\n    save('identity-after-replay.json', {'identity': IDENTITY, 'sentinel': sentinel})\n    assert 'n' not in report\n    assert {**report, 'n': IDENTITY[0]} == read('replay.json')\n    counts = dict(replay.LEDGER)\n    assert report['counts'] == counts == final['counts']\n    for name in ('producer-ledger.json', 'replay-ledger.json'):\n        assert read(name) == {'n': IDENTITY[0], 'counts': counts}\n    for key, expected in {'multiply': 21801456, 'divide': 716408, 'convert': 5083, 'negate': 356616, 'clip': 24386}.items():\n        assert signed[key] == counts[key] == expected\n    assert signed['products'] == 2032 and counts['coefficient_pairs'] == 21264880\n    assert counts['add'] == 21787232 == signed['plus'] + 21264880 + 1016\n    assert counts['scale'] == 2033 and counts['enlarge'] == 2034\n    assert sum(signed['sign_cases']) == signed['multiply']\n    assert signed['floor'] == signed['ceiling'] == signed['multiply'] + signed['divide'] + signed['convert'] + 1\n    expected = json.loads((OUT.parent / 'expected-endpoints.json').read_text())[str(IDENTITY[0])]\n    l, u, w = expected\n    assert final['n'] == IDENTITY[0] and final['final_grid'] == [l, u]\n    assert final['polynomial_sum'] == [l + 2 ** 72, u - 2 ** 72]\n    assert u - l == 2 ** 73 + w\n    assert Fraction(*final['midpoint']) == Fraction(l + u, 2 * D)\n    assert Fraction(*final['radius']) == Fraction(2 ** 73 + w, 2 * D) < Fraction(1, 2 ** 183) < Fraction(1, 2 ** 50)\n    assert final['required_radius'] == [1, 2 ** 50] and final['stronger_radius'] == [1, 2 ** 183]\n    assert read('parameter-identity.json') == {'n': IDENTITY[0], 'complete_record_equal': True, 'midpoint_unchanged': True}\n    status = read('status.json')\n    for key, value in {'status': 'PASS', 'n': IDENTITY[0], 'panels': 1016, 'pairs_per_pass': 21264880, 'parameter_complete_equal': True, 'ledger_equal': True, 'strict_radius_tests': [183, 50], 'radius': final['radius']}.items():\n        assert status[key] == value\n    save('complete-replay.json', {'status': 'PASS', 'n': IDENTITY[0], 'replay': report, 'immutable_ledger': counts, 'distinct_signed_checks': signed, 'parameter': parameter, 'kernel': final, 'sole_metadata_addition': 'n', 'producer_executed': False, 'strict_radius_powers': [183, 50]})\n    state.update(stage='complete', panels=1016)\n    save('status.json', {'status': 'PASS', 'state': state, 'elapsed_seconds': time.monotonic() - START})\n    print(json.dumps({'n': IDENTITY[0], 'status': 'PASS', 'panels': 1016, 'coefficient_pairs': counts['coefficient_pairs'], 'strict_radius_powers': [183, 50]}), flush=True)\nexcept BaseException as exc:\n    save('first-failure.json', {'type': type(exc).__name__, 'message': str(exc), 'state': state, 'traceback': traceback.format_exc()})\n    print(json.dumps({'n': IDENTITY[0], 'status': 'STOP', 'state': state, 'error': str(exc)}), flush=True)\n    sys.exit(1)\n"
INSTALLER="def install(replay, D, signed, save):\n    old_floor,old_ceil=replay.floor_checked,replay.ceil_checked\n    old_times,old_over=replay.times,replay.over\n    old_enc,old_plus=replay.enclose,replay.plus\n    old_neg,old_clip,old_product=replay.opposite,replay.intersect,replay.product\n    def floor_checked(n,d):\n        actual=old_floor(n,d)\n        assert d>0 and actual==n//d and actual*d<=n<(actual+1)*d\n        signed['floor']+=1\n        return actual\n    def ceil_checked(n,d):\n        actual=old_ceil(n,d)\n        assert d>0 and actual==-((-n)//d) and (actual-1)*d<n<=actual*d\n        signed['ceiling']+=1\n        return actual\n    def times(a,b):\n        actual=old_times(a,b)\n        al,au=a; bl,bu=b\n        extrema=(al*bl,al*bu,au*bl,au*bu)\n        assert actual==(min(extrema)//D,-((-max(extrema))//D))\n        ai=0 if al>=0 else 1 if au<=0 else 2\n        bi=0 if bl>=0 else 1 if bu<=0 else 2\n        signed['sign_cases'][3*ai+bi]+=1\n        signed['multiply']+=1\n        if a==(0,0) or b==(0,0): signed['zero_operand_multiplications']+=1\n        return actual\n    def over(a,k):\n        actual=old_over(a,k)\n        assert k>0 and a[0]<=a[1] and actual==(a[0]//k,-((-a[1])//k))\n        signed['divide']+=1\n        return actual\n    def enclose(n,d=1):\n        actual=old_enc(n,d)\n        assert d>0 and actual==((n*D)//d,-((-n*D)//d))\n        signed['convert']+=1\n        return actual\n    def plus(a,b):\n        actual=old_plus(a,b)\n        assert actual==(a[0]+b[0],a[1]+b[1])\n        signed['plus']+=1\n        return actual\n    def opposite(a):\n        actual=old_neg(a)\n        assert actual==(-a[1],-a[0])\n        signed['negate']+=1\n        return actual\n    def intersect(a,l,u):\n        actual=old_clip(a,l,u)\n        assert l<=u and actual==(max(a[0],l),min(a[1],u)) and actual[0]<=actual[1]\n        signed['clip']+=1\n        return actual\n    def product(a,b):\n        before=replay.LEDGER.get('coefficient_pairs',0)\n        actual=old_product(a,b)\n        assert replay.LEDGER['coefficient_pairs']-before==len(a)*len(b)\n        assert (len(a),len(b),len(actual)) in ((129,65,193),(193,65,257))\n        assert all(l<=u for l,u in actual)\n        signed['products']+=1\n        return actual\n    for name,fn in [('floor_checked',floor_checked),('ceil_checked',ceil_checked),('times',times),('over',over),\n        ('enclose',enclose),('plus',plus),('opposite',opposite),('intersect',intersect),('product',product)]: setattr(replay,name,fn)\n    intervals=[(-2*D,-D),(-D,0),(-D,D),(0,0),(0,D),(D,2*D)]\n    for a in intervals:\n        for b in intervals: times(a,b)\n    for n in (-2*D-1,-D,-1,0,1,D,2*D+1):\n        for d in (1,3,D): floor_checked(n,d); ceil_checked(n,d)\n    assert all(signed['sign_cases'])\n    save('primitive-controls.json',signed)\n    for key in signed: signed[key]=[0]*9 if key=='sign_cases' else 0\n    replay.LEDGER.clear()\n    return (floor_checked,ceil_checked,times,over,enclose,plus,opposite,intersect,product)\n"
PREFLIGHT="\nimport ast, copy, json, sys\nfrom pathlib import Path\nfrom types import SimpleNamespace\nsys.dont_write_bytecode=True\n\nimport hashlib, copy\nPRIMITIVES=('floor_checked','ceil_checked','times','over','enclose','plus','opposite','intersect','product')\ndef fresh_counts():\n    result={k:0 for k in ('floor','ceiling','multiply','divide','convert','plus','negate','clip','products','zero_operand_multiplications')}\n    result['sign_cases']=[0]*9\n    return result\ndef identity_for(index, output):\n    fixed=(Path('scripts/four-rational-kernels/step-417')/('n-'+str(index))).resolve()\n    return (index,str(fixed),str(Path(output).resolve()),'fixed_replay_422_'+str(index),hashlib.sha256((fixed/'replay.py').read_bytes()).hexdigest())\ndef check_identity(identity, fixed, output, module, original_module):\n    assert isinstance(identity,tuple) and len(identity)==5\n    assert type(identity[0]) is int and identity[0] in (3,4,5,6)\n    assert all(type(x) is str for x in identity[1:])\n    assert str(fixed.resolve())==identity[1] and str(output.resolve())==identity[2]\n    assert fixed.name==output.name=='n-'+str(identity[0])\n    assert module is original_module and module.__name__==identity[3]\n    assert Path(module.__file__).resolve()==fixed/'replay.py'\n    assert hashlib.sha256((fixed/'replay.py').read_bytes()).hexdigest()==identity[4]\n    assert module.SCALE==2**256\n\ndef check_captures(module, wrappers, originals, signed, grid):\n    assert len(wrappers)==9 and len({id(f) for f in wrappers})==9\n    old_names=('old_floor','old_ceil','old_times','old_over','old_enc','old_plus','old_neg','old_clip','old_product')\n    evidence=[]\n    for name,fn,old_name,old in zip(PRIMITIVES,wrappers,old_names,originals,strict=True):\n        assert getattr(module,name) is fn and fn is not old\n        closure=dict(zip(fn.__code__.co_freevars,(cell.cell_contents for cell in fn.__closure__),strict=True))\n        assert closure[old_name] is old and closure['signed'] is signed\n        if 'D' in closure: assert closure['D']==grid\n        if 'replay' in closure: assert closure['replay'] is module\n        evidence.append({'primitive':name,'closure_names':sorted(closure),'original_captured':True,'counter_captured':True})\n    return evidence\n\n\ndef inert_module(identity):\n    mod=SimpleNamespace(__name__=identity[3],__file__=str(Path(identity[1])/'replay.py'),SCALE=2**256,LEDGER={})\n    d=mod.SCALE\n    def floor(num,den): return num//den\n    def ceil(num,den): return -((-num)//den)\n    def times(a,b):\n        vals=[x*y for x in a for y in b]\n        mod.LEDGER['multiply']=mod.LEDGER.get('multiply',0)+1\n        return (mod.floor_checked(min(vals),d),mod.ceil_checked(max(vals),d))\n    def over(a,k): return (mod.floor_checked(a[0],k),mod.ceil_checked(a[1],k))\n    def enclose(num,den=1): return (mod.floor_checked(num*d,den),mod.ceil_checked(num*d,den))\n    def plus(a,b): return (a[0]+b[0],a[1]+b[1])\n    def opposite(a): return (-a[1],-a[0])\n    def intersect(a,l,u): return (max(a[0],l),min(a[1],u))\n    def product(a,b):\n        assert all(x==(0,0) for x in a+b)\n        mod.LEDGER['coefficient_pairs']=mod.LEDGER.get('coefficient_pairs',0)+len(a)*len(b)\n        return [(0,0)]*(len(a)+len(b)-1)\n    for name,fn in zip(PRIMITIVES,(floor,ceil,times,over,enclose,plus,opposite,intersect,product),strict=True): setattr(mod,name,fn)\n    return mod\n\ndef one(index,base,install):\n    IDENTITY=identity_for(index,base/('n-'+str(index)))\n    OLD=Path(IDENTITY[1]); OUT=Path(IDENTITY[2]); n=-422\n    before=(IDENTITY,OLD,OUT,n)\n    replay=inert_module(IDENTITY); original_module=replay\n    original_primitives=tuple(getattr(replay,k) for k in PRIMITIVES)\n    original_keys=set(vars(replay)); original_other={k:v for k,v in vars(replay).items() if k not in PRIMITIVES and k!='LEDGER'}\n    signed=fresh_counts(); callbacks=[]\n    def save(name,value): callbacks.append((name,copy.deepcopy(value)))\n    check_identity(IDENTITY,OLD,OUT,replay,original_module)\n    wrappers=install(replay,replay.SCALE,signed,save)\n    assert before==(IDENTITY,OLD,OUT,n) and n==-422\n    check_identity(IDENTITY,OLD,OUT,replay,original_module)\n    assert set(vars(replay))==original_keys\n    assert {k:v for k,v in vars(replay).items() if k not in PRIMITIVES and k!='LEDGER'}==original_other\n    captures=check_captures(replay,wrappers,original_primitives,signed,replay.SCALE)\n    expected=fresh_counts(); expected.update(floor=57,ceiling=57,multiply=36,zero_operand_multiplications=11)\n    expected['sign_cases']=[9,6,3,6,4,2,3,2,1]\n    assert callbacks==[('primitive-controls.json',expected)]\n    assert signed==fresh_counts() and replay.LEDGER=={}\n    # Exercise each retained closure after installer return, without any numerical kernel.\n    d=replay.SCALE\n    assert replay.floor_checked(-4,3)==-2 and replay.ceil_checked(-4,3)==-1\n    assert replay.times((-d,d),(0,d))==(-d,d)\n    assert replay.over((-4,4),3)==(-2,2)\n    assert replay.enclose(0)==(0,0)\n    assert replay.plus((-1,0),(0,1))==(-1,1)\n    assert replay.opposite((-1,2))==(-2,1)\n    assert replay.intersect((-d,d),0,d)==(0,d)\n    assert replay.product([(0,0)]*129,[(0,0)]*65)==[(0,0)]*193\n    assert signed['products']==1 and replay.LEDGER['coefficient_pairs']==8385\n    assert before==(IDENTITY,OLD,OUT,n) and len(callbacks)==1\n    check_identity(IDENTITY,OLD,OUT,replay,original_module)\n    return {'n':index,'identity':IDENTITY,'sentinel':n,'status':'PASS','all_nine_replacements':True,'captures':captures,'controls':expected,'post_return_counts':copy.deepcopy(signed),'post_return_ledger':copy.deepcopy(replay.LEDGER),'kernel_executed':False,'callbacks':len(callbacks)}\n\ndef preflight(base, installer_source):\n    ns={}\n    exec(compile(installer_source,'installer-preflight-422','exec'),ns)\n    results=[]\n    for index in (3,4,5,6): results.append(one(index,base,ns['install']))\n    assert len({row['identity'][3] for row in results})==4\n    return results\n"
PARENT='\nimport ast,difflib,hashlib,json,math,signal,subprocess,sys,textwrap,traceback\nfrom pathlib import Path\nsys.dont_write_bytecode=True\nROOT=Path.cwd(); OLD=ROOT/\'scripts/four-rational-kernels/step-417\'; OUT=ROOT/\'scripts/four-rational-kernels/step-422\'\nLIMIT=134217728; RESERVE=73728\ninitial={}; names={}; sources={}; exits=[]; completed=[]; failure=None; current=None\nroots=[ROOT/\'scripts/first-rational-kernel\',ROOT/\'scripts/second-rational-kernel\',ROOT/\'scripts/finite-derivative-coefficients\',OLD,ROOT/\'scripts/four-rational-kernels/step-419\']\ndef alarm(*args): raise TimeoutError(\'aggregate_terminal_deadline\')\nsignal.signal(signal.SIGALRM,alarm); signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\nOUT.mkdir()\nbootstrap=\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(WORKER)+\'\\nINSTALLER=\'+repr(INSTALLER)+\'\\nPREFLIGHT=\'+repr(PREFLIGHT)+\'\\nPARENT=\'+repr(PARENT)+\'\\nexec(compile(PARENT,"isolated-audit-parent-422","exec"))\\n\'\n(OUT/\'bootstrap.py\').write_text(bootstrap)\n(OUT/\'worker.py\').write_text(WORKER)\n(OUT/\'installer.py\').write_text(INSTALLER)\n(OUT/\'preflight.py\').write_text(PREFLIGHT)\ndef disk(): return sum(p.stat().st_size for p in OUT.rglob(\'*\') if p.is_file())\ndef sha(raw): return hashlib.sha256(raw).hexdigest()\ndef inventory(paths):\n    answer={}\n    for p in sorted(set(paths)):\n        raw=p.read_bytes(); answer[str(p.relative_to(ROOT))]={\'bytes\':len(raw),\'sha256\':sha(raw)}\n    return answer\ndef tree_names(): return {str(root.relative_to(ROOT)):sorted(str(p.relative_to(ROOT)) for p in root.rglob(\'*\') if p.is_file()) for root in roots}\ndef save(name,obj):\n    raw=(json.dumps(obj,sort_keys=True,separators=(\',\',\':\'))+\'\\n\').encode()\n    assert disk()+len(raw)+RESERVE<=LIMIT\n    (OUT/name).write_bytes(raw)\ndef read(name): return json.loads((OLD/name).read_text())\ndef workcheck():\n    assert time.monotonic()-START<174 and disk()+RESERVE<=LIMIT\ntry:\n    original=read(\'initial-inventory.json\'); assert len(original)==95\n    names=tree_names()\n    selected=[\'lemmas/L105-four-fixed-rational-kernel-certificates.md\',\'drafts/literature/2026-10-23-four-kernel-certificate-audit.md\',\'drafts/source-notes/2026-10-23-four-kernel-audit-coverage.md\',\'drafts/2026-10-23-four-kernel-document-transition.json\',\'drafts/2026-10-23-four-kernel-critical-audit.md\']\n    selected += [\'drafts/2026-10-23-four-kernel-audit-document-transition.json\',\'drafts/2026-10-23-four-kernel-audit-static-diagnosis.json\',\'drafts/source-notes/2026-10-23-isolated-audit-control-scope.md\',\'drafts/literature/2026-10-23-isolated-four-kernel-audit.md\',\'drafts/2026-10-23-isolated-four-kernel-critical-audit.md\',\'ATTEMPTS/047-four-kernel-audit-control-index-collision.md\']\n    stopped=ROOT/\'scripts/four-rational-kernels/step-419\'\n    stopped_inventory=json.loads((stopped/\'initial-inventory.json\').read_text())\n    initial=inventory([ROOT/p for p in original]+[ROOT/p for p in stopped_inventory]+[p for root in (OLD,stopped) for p in root.rglob(\'*\') if p.is_file()]+[ROOT/p for p in selected])\n    editorial=json.loads((ROOT/\'drafts/2026-10-23-four-kernel-audit-document-transition.json\').read_text())\n    assert set(editorial[\'files\'])=={\'lemmas/L105-four-fixed-rational-kernel-certificates.md\',\'drafts/2026-10-23-four-kernel-critical-audit.md\'}\n    for rel,entry in editorial[\'files\'].items():\n        assert stopped_inventory[rel]==entry[\'before\'] and initial[rel]==entry[\'after\']\n    for rel,value in stopped_inventory.items():\n        assert initial[rel]==(editorial[\'files\'][rel][\'after\'] if rel in editorial[\'files\'] else value),(\'post419_identity\',rel)\n    stopped_preservation=json.loads((stopped/\'preservation.json\').read_text())\n    assert stopped_preservation[\'all_match\'] and stopped_preservation[\'files\']==stopped_inventory\n    stopped_sources=json.loads((stopped/\'fresh-source-hashes.json\').read_text())\n    assert inventory([ROOT/p for p in stopped_sources])==stopped_sources\n    save(\'post419-reconciliation.json\',{\'editorial\':editorial,\'all_stopped_inputs_match\':True,\'stopped_sources_match\':True,\'stopped_files\':len(stopped_inventory)})\n    save(\'initial-inventory.json\',initial)\n    transition=json.loads((ROOT/selected[3]).read_text())\n    changed=\'drafts/2026-10-23-four-kernel-attempt.md\'\n    assert set(transition[\'files\'])=={changed}\n    assert transition[\'files\'][changed][\'before\']==original[changed]\n    assert transition[\'files\'][changed][\'after\']==initial[changed]\n    for rel,value in original.items():\n        assert initial[rel]==(transition[\'files\'][rel][\'after\'] if rel in transition[\'files\'] else value),(\'original_input\',rel)\n    for root in roots[:3]:\n        prefix=str(root.relative_to(ROOT))+\'/\'\n        assert names[str(root.relative_to(ROOT))]==sorted(p for p in original if p.startswith(prefix))\n    assert read(\'preservation.json\')=={\'count\':95,\'files\':original,\'mismatches\':[],\'original_tree_file_sets_equal\':True,\'fresh_sources_equal\':True,\'all_match\':True}\n    # Parse old bootstrap solely as data; never execute worker or parent entrypoints.\n    tree=ast.parse((OLD/\'bootstrap.py\').read_text())\n    literals={node.targets[0].id:ast.literal_eval(node.value) for node in tree.body if isinstance(node,ast.Assign) and isinstance(node.targets[0],ast.Name) and node.targets[0].id in (\'WORKER\',\'PARENT\')}\n    assert set(literals)=={\'WORKER\',\'PARENT\'}\n    assert literals[\'WORKER\']==(OLD/\'worker.py\').read_text()\n    assert (OLD/\'bootstrap.py\').read_text()==\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(literals[\'WORKER\'])+\'\\nPARENT=\'+repr(literals[\'PARENT\'])+\'\\nexec(compile(PARENT,"batch-parent","exec"))\\n\'\n    parent_tree=ast.parse(literals[\'PARENT\'])\n    nodes=[x for x in ast.walk(parent_tree) if isinstance(x,ast.Assign) and any(isinstance(t,ast.Name) and t.id==\'replacements\' for t in x.targets)]\n    assert len(nodes)==1\n    # Only this inspected data expression is evaluated: constants, f-strings, n and str(n).\n    allowed=(ast.Dict,ast.List,ast.Tuple,ast.Constant,ast.JoinedStr,ast.FormattedValue,ast.Name,ast.Load,ast.BinOp,ast.Add,ast.Call)\n    assert all(isinstance(x,allowed) for x in ast.walk(nodes[0].value))\n    assert all(x.id in (\'n\',\'str\') for x in ast.walk(nodes[0].value) if isinstance(x,ast.Name))\n    assert all(isinstance(x.func,ast.Name) and x.func.id==\'str\' for x in ast.walk(nodes[0].value) if isinstance(x,ast.Call))\n    source_hashes=read(\'source-hashes.json\')\n    assert len(source_hashes)==10 and inventory([ROOT/p for p in source_hashes])==source_hashes\n    assert set(source_hashes)=={str((OLD/f).relative_to(ROOT)) for f in (\'bootstrap.py\',\'worker.py\')}|{str((OLD/(\'n-\'+str(n))/f).relative_to(ROOT)) for n in (3,4,5,6) for f in (\'producer.py\',\'replay.py\')}\n    reviews=[]\n    for n in (3,4,5,6):\n        dest=OLD/(\'n-\'+str(n)); review=json.loads((dest/\'source-review.json\').read_text())\n        transforms=eval(compile(ast.Expression(nodes[0].value),\'data-expression\',\'eval\'),{\'__builtins__\':{},\'str\':str},{\'n\':n})\n        assert review=={\'n\':n,\'unique_exact_changes\':{k:[{\'old\':a,\'new\':b} for a,b in v] for k,v in transforms.items()},\'both_scalar_and_beta_arguments_bound\':True,\'midpoint_not_scaled\':True,\'all_independent_arithmetic_and_full_loops_unchanged\':True}\n        differences=[]\n        for name,pairs in transforms.items():\n            before=(ROOT/\'scripts/second-rational-kernel/step-412\'/name).read_text(); after=before\n            for a,b in pairs:\n                assert after.count(a)==1; after=after.replace(a,b,1)\n            assert after==(dest/name).read_text(); ast.parse(after)\n            differences.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile=\'step-412/\'+name,tofile=\'n-\'+str(n)+\'/\'+name))\n        assert \'\'.join(differences)==(dest/\'source-diff.txt\').read_text()\n        reviews.append(review)\n    manifest=read(\'manifest.json\')\n    expected={\'step\':\'BSD-2026-10-23-417-four-kernel-batch\',\'indices\':[3,4,5,6],\'required_seconds\':180,\'work_deadline_seconds\':174,\'required_new_bytes\':LIMIT,\'report_and_diagnostic_reserve\':RESERVE,\'midpoint\':\'unchanged complete L103 record\',\'panels_per_kernel\':1016,\'factor_slots\':[129,65,65],\'product_slots\':[193,257],\'pairs_per_pass\':21264880,\'scalar_terms\':128,\'scalar_squares\':16,\'grid_fractional_bits\':256,\'analytic_enlargement_grid\':2**72,\'strict_radius_powers\':[183,50],\'source_generation_in_cap\':True,\'isolated_modules_per_child\':True,\'old_entrypoints_executed\':False,\'no_retry_or_resumption\':True}\n    assert {k:v for k,v in manifest.items() if k!=\'python\'}==expected\n    assert manifest[\'python\'].startswith(\'3.15.0\')\n    term=read(\'terminal-report.json\'); fin=read(\'finalization.json\'); hist_exits=read(\'observed-child-exits.json\'); hist_completed=read(\'completed-kernels.json\')\n    assert term[\'child_exits\']==hist_exits and term[\'completed_indices\']==[3,4,5,6]\n    assert term[\'status\']==\'PASS\' and term[\'failure\'] is None and term[\'preservation\'] and term[\'preserved_inputs\']==95 and term[\'terminal_timer_retained\']\n    assert term[\'required_seconds\']==180 and term[\'required_new_bytes\']==LIMIT and term[\'path\']==\'scripts/four-rational-kernels/step-417/terminal-report.json\'\n    prev=0\n    for n,ex,st in zip((3,4,5,6),hist_exits,hist_completed,strict=True):\n        assert ex[\'n\']==n and ex[\'returncode\']==0 and prev<ex[\'start_seconds\']<ex[\'observed_exit_seconds\']<term[\'elapsed_before_terminal_seconds\']\n        prev=ex[\'observed_exit_seconds\']\n        dest=OLD/(\'n-\'+str(n)); assert st==json.loads((dest/\'status.json\').read_text())\n        assert st[\'elapsed_seconds\']<ex[\'observed_exit_seconds\']\n        work=json.loads((dest/\'working.json\').read_text()); assert work[\'n\']==n and work[\'stage\']==\'replay\' and work[\'panels\']==961 and work[\'elapsed_seconds\']<st[\'elapsed_seconds\']\n        output=json.loads((dest/\'child-stdout.txt\').read_text()); assert output=={\'n\':n,\'status\':\'PASS\',\'radius\':st[\'radius\']}\n        assert (dest/\'child-stderr.txt\').read_bytes()==b\'\'\n    fixed=list(OLD.rglob(\'*\')); before=sum(p.stat().st_size for p in fixed if p.is_file() and p.name not in (\'terminal-report.json\',\'finalization.json\'))\n    assert before+RESERVE==term[\'inclusive_new_bytes\']==fin[\'inclusive_new_bytes\']==6025081\n    assert math.ceil(term[\'elapsed_before_terminal_seconds\'])+2==term[\'inclusive_seconds\']==fin[\'inclusive_seconds\']==105\n    assert before+(OLD/\'terminal-report.json\').stat().st_size==fin[\'new_bytes_after_terminal\']\n    assert term[\'elapsed_before_terminal_seconds\']<fin[\'elapsed_after_terminal_seconds\']<105\n    assert fin[\'all_children_observed_before_terminal\'] and fin[\'parent_exit_time_not_claimed\'] and fin[\'terminal_timer_retained\']\n    assert sum(p.stat().st_size for p in fixed if p.is_file())+8192<=6025081\n    save(\'historical-review.json\',{\'manifest\':manifest,\'source_reviews\':reviews,\'source_hashes\':source_hashes,\'exact_bootstrap_worker_and_adaptations\':True,\'transition\':transition,\'terminal\':term,\'finalization\':fin,\'before_terminal_bytes\':before,\'qualification\':\'Historical n=1 finalization, n=2 bootstrap/process exit and step-417 exact parent exit remain unverified as originally qualified.\'})\n    # Static review of the actual lexical installer and immutable worker binding precedes any controls.\n    retained=(ROOT/\'scripts/four-rational-kernels/step-419/signed-checks.py\').read_text()\n    comparison=(ROOT/\'scripts/second-rational-kernel/step-415/audit-body.py\').read_text()\n    left=\'    old_floor,old_ceil=replay.floor_checked,replay.ceil_checked\\n\'; right="    parameter=read(\'parameter.json\')\\n"\n    assert comparison.count(left)==comparison.count(right)==1\n    assert textwrap.dedent(comparison[comparison.index(left):comparison.index(right)])==retained\n    parsed=ast.parse(INSTALLER)\n    assert len(parsed.body)==1 and isinstance(parsed.body[0],ast.FunctionDef)\n    fn=parsed.body[0]\n    assert fn.name==\'install\' and [x.arg for x in fn.args.args]==[\'replay\',\'D\',\'signed\',\'save\']\n    assert not fn.args.defaults and not fn.decorator_list and fn.returns is None\n    assert all(arg.annotation is None for arg in fn.args.args)\n    assert ast.dump(ast.Module(body=fn.body[:-1],type_ignores=[]),include_attributes=False)==ast.dump(ast.parse(retained),include_attributes=False)\n    assert isinstance(fn.body[-1],ast.Return)\n    assert not any(isinstance(x,(ast.Global,ast.Nonlocal,ast.Import,ast.ImportFrom)) for x in ast.walk(fn))\n    assert not {\'OUT\',\'OLD\',\'START\',\'IDENTITY\',\'globals\',\'locals\',\'exec\',\'eval\',\'compile\',\'__import__\'} & {x.id for x in ast.walk(fn) if isinstance(x,ast.Name)}\n    defaults=[]\n    for node in ast.walk(fn):\n        if isinstance(node,ast.FunctionDef):\n            assert not node.decorator_list and node.returns is None\n            assert all(x.annotation is None for x in node.args.args)\n            for val in node.args.defaults: assert isinstance(val,ast.Constant) and val.value==1\n            defaults.extend(ast.unparse(val) for val in node.args.defaults)\n    calls=sorted({ast.unparse(x.func) for x in ast.walk(fn) if isinstance(x,ast.Call)})\n    assert set(calls)=={\'old_floor\',\'old_ceil\',\'old_times\',\'old_over\',\'old_enc\',\'old_plus\',\'old_neg\',\'old_clip\',\'old_product\',\'min\',\'max\',\'len\',\'all\',\'setattr\',\'times\',\'floor_checked\',\'ceil_checked\',\'save\',\'replay.LEDGER.get\',\'replay.LEDGER.clear\'}\n    stores=[ast.unparse(x) for x in ast.walk(fn) if isinstance(x,(ast.Name,ast.Attribute,ast.Subscript)) and isinstance(x.ctx,ast.Store)]\n    worker_ast=ast.parse(WORKER)\n    identity_stores=[x for x in ast.walk(worker_ast) if isinstance(x,ast.Name) and x.id==\'IDENTITY\' and isinstance(x.ctx,ast.Store)]\n    assert len(identity_stores)==1\n    assert not any(isinstance(x,ast.Subscript) and isinstance(x.ctx,ast.Store) and isinstance(x.value,ast.Name) and x.value.id==\'IDENTITY\' for x in ast.walk(worker_ast))\n    assert not any(isinstance(x,ast.Name) and x.id==\'n\' for x in ast.walk(worker_ast))\n    save(\'static-binding-review.json\',{\'status\':\'PASS\',\'installer_body_exact\':True,\'identity_binding_sites\':len(identity_stores),\'calls\':calls,\'stores\':stores,\'defaults\':defaults,\'installer_sha256\':sha(INSTALLER.encode()),\'worker_sha256\':sha(WORKER.encode()),\'preflight_sha256\':sha(PREFLIGHT.encode())})\n    preflight_namespace={}\n    exec(compile(PREFLIGHT,\'inert-preflight-422\',\'exec\'),preflight_namespace)\n    preflight_result=preflight_namespace[\'preflight\'](OUT,INSTALLER)\n    save(\'identity-preflight.json\',{\'status\':\'PASS\',\'indices\':[3,4,5,6],\'results\':preflight_result,\'all_before_any_kernel\':True,\'elapsed_seconds\':time.monotonic()-START})\n    workcheck()\n    endpoints={}\n    for line in (ROOT/selected[0]).read_text().splitlines():\n        if line.startswith(\'| \') and line.split(\'|\')[1].strip() in (\'3\',\'4\',\'5\',\'6\'):\n            values=[int(v.strip()) for v in line.split(\'|\')[1:-1]]; endpoints[str(values[0])]=values[1:]\n    assert set(endpoints)=={\'3\',\'4\',\'5\',\'6\'} and [endpoints[str(n)][2] for n in (3,4,5,6)]==[922672,466423,252182,142692]\n    save(\'expected-endpoints.json\',endpoints)\n    sources=inventory([OUT/\'bootstrap.py\',OUT/\'worker.py\',OUT/\'installer.py\',OUT/\'preflight.py\',OUT/\'expected-endpoints.json\'])\n    save(\'fresh-source-hashes.json\',sources)\n    save(\'audit-manifest.json\',{\'python\':sys.version,\'indices\':[3,4,5,6],\'time_cap_seconds\':180,\'byte_cap\':LIMIT,\'start_before_setup\':True,\'old_entrypoints_executed\':False,\'source_generation_in_cap\':True,\'signed_checks\':\'function-scoped exact retained block; static binding and four inert preflights before any kernel; all full original arithmetic comparisons retained\'})\n    for n in (3,4,5,6):\n        current=n; workcheck(); dest=OUT/(\'n-\'+str(n)); dest.mkdir(); t=time.monotonic()-START\n        try:\n            result=subprocess.run([sys.executable,\'-B\',str(OUT/\'worker.py\'),str(n),str(dest),repr(START)],capture_output=True,timeout=max(.001,174-(time.monotonic()-START)))\n            stdout,stderr,code=result.stdout,result.stderr,result.returncode\n        except subprocess.TimeoutExpired as exc:\n            stdout,stderr,code=exc.stdout or b\'\',exc.stderr or b\'\',None\n            failure={\'type\':\'ChildTimeout\',\'n\':n,\'message\':\'child killed and waited; no retry\'}\n        assert len(stdout)+len(stderr)<=8192\n        (dest/\'child-stdout.txt\').write_bytes(stdout); (dest/\'child-stderr.txt\').write_bytes(stderr)\n        exits.append({\'n\':n,\'returncode\':code,\'start_seconds\':t,\'observed_exit_seconds\':time.monotonic()-START}); save(\'observed-child-exits.json\',exits)\n        if failure is not None: break\n        if code!=0:\n            failure={\'type\':\'ChildFailure\',\'n\':n,\'returncode\':code,\'evidence\':str((dest/\'first-failure.json\').relative_to(ROOT))}; break\n        completed.append(n); save(\'completed-indices.json\',completed)\n        print(json.dumps({\'n\':n,\'status\':\'PASS\',\'observed_exit_seconds\':exits[-1][\'observed_exit_seconds\']}),flush=True)\n        workcheck()\nexcept BaseException as exc:\n    if failure is None: failure={\'type\':type(exc).__name__,\'message\':str(exc),\'n\':current,\'traceback\':traceback.format_exc()}\nfinally:\n    signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\n    after=inventory([ROOT/p for p in initial]); mismatch=[p for p in initial if initial[p]!=after.get(p)]\n    preserved=not mismatch and tree_names()==names and inventory([ROOT/p for p in sources])==sources\n    save(\'preservation.json\',{\'count\':len(initial),\'files\':after,\'mismatches\':mismatch,\'all_match\':preserved,\'tree_sets_equal\':tree_names()==names,\'fresh_sources_equal\':inventory([ROOT/p for p in sources])==sources})\n    if not preserved and failure is None: failure={\'type\':\'PreservationFailure\',\'message\':str(mismatch)}\n    if failure is not None: save(\'first-failure.json\',failure)\n    elapsed=time.monotonic()-START; sec=math.ceil(elapsed)+2; size=disk()+RESERVE\n    okay=failure is None and completed==[3,4,5,6] and sec<=180 and size<=LIMIT\n    terminal={\'status\':\'PASS\' if okay else \'STOP\',\'completed_indices\':completed,\'failure\':failure,\'child_exits\':exits,\'preserved_inputs\':len(initial),\'preservation\':preserved,\'elapsed_before_terminal_seconds\':elapsed,\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\'required_seconds\':180,\'required_new_bytes\':LIMIT,\'terminal_timer_retained\':True,\'path\':str((OUT/\'terminal-report.json\').relative_to(ROOT))}\n    save(\'terminal-report.json\',terminal)\n    # Rehash again after terminal reporting, so the preservation boundary covers reporting.\n    assert inventory([ROOT/p for p in initial])==initial and tree_names()==names and inventory([ROOT/p for p in sources])==sources\n    save(\'finalization.json\',{\'elapsed_after_terminal_seconds\':time.monotonic()-START,\'new_bytes_after_terminal\':disk(),\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\'all_children_observed_before_terminal\':True,\'preservation_rechecked_after_terminal\':True,\'parent_exit_time_not_claimed\':True,\'terminal_timer_retained\':True})\n    assert time.monotonic()-START<=sec<=180 and disk()+8192<=size<=LIMIT\n    print(json.dumps(terminal),flush=True)\n    assert time.monotonic()-START<=sec\n    sys.exit(0 if okay else 1)\n'
